#define main bridge_program_main
#include "bridge.c"
#include "ids.h"
#undef main
static int errors;static void check(bool x,const char*s){printf("%s %s\n",x?"PASS":"FAIL",s);if(!x)errors++;}
static void icon(int cell){for(int y=0;y<200;y++)for(int x=0;x<320;x++)if(ui_command_from_mouse(TABLES_MOUSE_INTERFACE,x,y,UI_BUTTON_LEFT)==COMMAND_CLICK_CHAMPION_ICON_FIRST+cell){printf("ICON cell%d x%d y%d\n",cell,x,y);command_process_click(x,y,CLICK_LEFT_PRESS);command_process_click(x,y,CLICK_LEFT_RELEASE);gameloop_run_commands();return;}}
int main(int n,char**a){if(n<2||!init(a[1]))return 2;connection(0,true);connection(1,true);unsigned char portraits[8][32*29];char names[8][8];for(int p=0;p<2;p++){select_party(p);for(int c=0;c<4;c++){memcpy(portraits[p*4+c],g_champions[c].runtime.portrait,32*29);memcpy(names[p*4+c],g_champions[c].name,8);printf("CHAMPION %d %s\n",p,g_champions[c].name);}}for(int i=0;i<8;i++)for(int j=0;j<i;j++){check(strcmp(names[i],names[j])!=0,"eight different names");check(memcmp(portraits[i],portraits[j],32*29)!=0,"eight different original portraits");}
for(int p=0;p<2;p++){select_party(p);int a=champion_get_index_in_cell(g_party_direction),b=champion_get_index_in_cell((g_party_direction+1)%4),ca=g_champions[a].cell,cb=g_champions[b].cell;icon(0);for(int t=0;t<6;t++){select_party(1-p);redraw();select_party(p);redraw();}icon(1);check(g_champions[a].cell==cb&&g_champions[b].cell==ca,"two original icon clicks swap across polling and other party");}
select_party(0);g_champions[0].runtime.pending_damage=17;champion_apply_pending_damage();redraw();unsigned char marked[sizeof g_screen.px],clear[sizeof g_screen.px];memcpy(marked,g_screen.px,sizeof marked);redraw();check(memcmp(marked,g_screen.px,sizeof marked)==0,"incoming damage stable across redraw");g_champions[0].runtime.recent_damage=0;redraw();memcpy(clear,g_screen.px,sizeof clear);check(memcmp(marked,clear,sizeof clear)!=0,"incoming damage original splat visible");
select_party(0);g_party_map_x=1;g_party_map_y=14;g_party_direction=2;g_champions[0].cell=2;g_champions[0].direction=2;g_champions[1].cell=3;g_champions[2].cell=0;g_champions[3].cell=1;redraw();uint16_t group=map_find_thing((Location){1,15},THING_GROUP);printf("MELEE target=%u\n",group);int dealt=0;if(group!=THING_ENDOFLIST){for(int i=0;i<30&&!dealt;i++){int before=0;for(int z=0;z<=rec_group_last_creature(group);z++)before+=rec_group_health(group,z);action_is_action_performed(0,ACTION_SWING);int16_t damage=-99;if(action_recent_melee(&damage)&&damage>0){int after=0;for(int z=0;z<=rec_group_last_creature(group);z++)after+=rec_group_health(group,z);dealt=before>after;printf("MELEE originaldamage=%d hp=%d->%d\n",damage,before,after);}}}check(dealt,"original sword melee really reduces creature health");redraw();memcpy(marked,g_screen.px,sizeof marked);redraw();check(memcmp(marked,g_screen.px,sizeof marked)==0,"outgoing original damage survives frame rebuild");select_party(0);g_party_map_x=8;g_party_map_y=1;select_party(1);g_party_map_x=1;g_party_map_y=14;int initial=0;for(int i=0;i<4;i++)initial+=g_champions[i].current_health;int final=initial;for(int t=0;t<640&&final>=initial;t++){select_party(0);gameloop_tick();select_party(1);final=0;for(int i=0;i<4;i++)final+=g_champions[i].current_health;}printf("CREATURE BHP=%d->%d\n",initial,final);check(final<initial,"original creature can damage different-party champions");return errors?1:0;}
